import os

def find_submission_scripts(base_dir, max_depth=2):
    found = []
    visited = set()

    def search(path, depth):
        if depth > max_depth:
            return
        if path in visited:
            return
        visited.add(path)

        try:
            items = os.listdir(path)
        except PermissionError:
            return

        for item in sorted(items):
            full_path = os.path.join(path, item)

            # Skip hidden and common dirs
            if item.startswith('.'):
                continue

            stat = os.stat(full_path)

            if stat.st_mode & 0o40000:  # directory
                if not item in ['__pycache__', 'node_modules', '.git', 'venv', 'env']:
                    search(full_path, depth + 1)
            elif stat.st_mode & 0o100000:  # file
                name = item.lower()
                if 'submit' in name or 'api' in name or 'eval' in name:
                    found.append(full_path)

    search(base_dir, 0)
    return found

